INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active")
VALUES ('417bcbcf-1354-516f-96af-7bbe5897bffb'::uuid, 'CAP037_L1', (SELECT "id" FROM public."capabilities" WHERE "code" = 'ITS-CAP-037'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 1), 'Recognise and Safely Inspect GenAI Workflows', 'Northstar Retail is preparing a GenAI customer-support assistant that answers customer questions using approved business information. A generated response appears polished and confident, but the supplied records may show conflict with an approved source, internal-use information appearing in customer-facing output, incomplete review evidence, unclear source or review status, and deadline pressure encouraging premature use. The learner must inspect supplied records, identify workflow objects, classify evidence, recognise visible quality, evidence and boundary signals, record uncertainty, organise a safe review handoff and prepare a permitted first review action without diagnosing the technical cause, changing the response, approving the output or closing the case.', '["Identify workflow objects", "classify supplied evidence", "recognise visible quality evidence and boundary signals", "record uncertainty", "organise a review handoff", "prepare a safe first review action"]'::jsonb, '["GenAI Workflow Entry Record", "Annotated GenAI Workflow Map", "Evidence Classification Register", "GenAI Response Signal Scan", "GenAI Workflow Review Handoff Pack", "Safe First Review Action Record", "L1 Evidence Review Portfolio and Transfer Pack"]'::jsonb, '{"title": "Recognise and Safely Inspect GenAI Workflows", "description": "Northstar Retail is preparing a GenAI customer-support assistant that answers customer questions using approved business information. A generated response appears polished and confident, but the supplied records may show conflict with an approved source, internal-use information appearing in customer-facing output, incomplete review evidence, unclear source or review status, and deadline pressure encouraging premature use. The learner must inspect supplied records, identify workflow objects, classify evidence, recognise visible quality, evidence and boundary signals, record uncertainty, organise a safe review handoff and prepare a permitted first review action without diagnosing the technical cause, changing the response, approving the output or closing the case."}'::jsonb, 420, 'beginner'::public.difficulty_level, 'published'::public.status, 1, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active")
VALUES ('02c85598-3f29-50f3-bdba-deea3d62de79'::uuid, 'CAP037_L2', (SELECT "id" FROM public."capabilities" WHERE "code" = 'ITS-CAP-037'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 2), 'Build and Test a GenAI Workflow with Support', 'Northstar Retail needs a controlled GenAI customer-support workflow prepared for sandbox testing. The GenAI Workflow Owner supplies an approved workflow request, a structured prompt template, approved and restricted source records, a controlled sandbox, defined test cases and permitted revision rules. The learner must complete assigned workflow fields, assemble approved prompt components, connect permitted source context, run supplied tests, record evidence, make only explicitly permitted routine revisions and submit a versioned evidence pack. The learner may not independently design the complete workflow, use unapproved sources, change protected controls, approve customer-facing output, deploy to production or close significant exceptions.', '["Translate approved workflow requests", "assemble approved prompt components", "connect approved context", "configure assigned sandbox fields", "run supplied tests", "make authorised routine revisions", "prepare evidence handoff"]'::jsonb, '["L2 Readiness and Authority Record", "Workflow Requirement Brief", "Prompt Assembly Record", "Source Connection Checklist", "Sandbox Configuration Record", "Test Execution Log", "Supported GenAI Workflow Build and Test Pack"]'::jsonb, '{"title": "Build and Test a GenAI Workflow with Support", "description": "Northstar Retail needs a controlled GenAI customer-support workflow prepared for sandbox testing. The GenAI Workflow Owner supplies an approved workflow request, a structured prompt template, approved and restricted source records, a controlled sandbox, defined test cases and permitted revision rules. The learner must complete assigned workflow fields, assemble approved prompt components, connect permitted source context, run supplied tests, record evidence, make only explicitly permitted routine revisions and submit a versioned evidence pack. The learner may not independently design the complete workflow, use unapproved sources, change protected controls, approve customer-facing output, deploy to production or close significant exceptions."}'::jsonb, 420, 'foundation'::public.difficulty_level, 'published'::public.status, 1, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active")
VALUES ('54eb917e-e5a9-5ebf-8c8d-cd8bac472907'::uuid, 'CAP037_L3', (SELECT "id" FROM public."capabilities" WHERE "code" = 'ITS-CAP-037'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 3), 'Build and Validate Standard GenAI Workflows', 'Northstar Retail requires a standard GenAI workflow to be designed, configured and validated for a defined customer-support use case. The learner receives an approved business objective, standard design constraints, approved source boundaries and acceptance criteria, but must independently convert them into a complete prompt workflow, configure retrieval context, prepare a validation plan, execute standard tests, resolve routine defects and submit a defensible validation handoff. The learner may make routine design and correction decisions within approved patterns, but must escalate ambiguous, high-risk, policy, security, privacy or production-release decisions.', '["Define workflow objective and acceptance criteria", "design standard prompt workflow", "configure approved context and retrieval", "build validation plan", "execute tests", "resolve routine defects", "prepare validation handoff"]'::jsonb, '["L3 Builder Readiness and Authority Record", "Workflow Objective and Acceptance Criteria Brief", "Prompt Workflow Design Record", "Context Configuration and Retrieval Record", "Workflow Validation Test Plan", "Test Run and Routine Defect Resolution Log", "Standard GenAI Workflow Validation Handoff Pack"]'::jsonb, '{"title": "Build and Validate Standard GenAI Workflows", "description": "Northstar Retail requires a standard GenAI workflow to be designed, configured and validated for a defined customer-support use case. The learner receives an approved business objective, standard design constraints, approved source boundaries and acceptance criteria, but must independently convert them into a complete prompt workflow, configure retrieval context, prepare a validation plan, execute standard tests, resolve routine defects and submit a defensible validation handoff. The learner may make routine design and correction decisions within approved patterns, but must escalate ambiguous, high-risk, policy, security, privacy or production-release decisions."}'::jsonb, 420, 'intermediate'::public.difficulty_level, 'published'::public.status, 1, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active")
VALUES ('0899a455-1166-5d00-810d-8594e8c29ef9'::uuid, 'CAP037_L4', (SELECT "id" FROM public."capabilities" WHERE "code" = 'ITS-CAP-037'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 4), 'Adapt GenAI Workflows for Complex and Ambiguous Conditions', 'Northstar Retail must adapt an existing GenAI workflow for a more complex customer-support environment involving incomplete requirements, competing business constraints, variable source quality, ambiguous user needs and higher operational risk. The learner must interpret ambiguity, compare design options, adapt prompt and context strategies, expand test coverage, evaluate evidence and recommend a defensible workflow design with clear trade-offs, assumptions, residual risks and escalation points. The learner may recommend adaptive changes but may not bypass governance, make unsupported policy decisions or independently authorise production release.', '["Interpret ambiguity", "compare workflow options", "adapt context and retrieval", "design expanded validation", "evaluate conflicting evidence", "recommend a defensible adaptive design"]'::jsonb, '["Adaptive Authority and Ambiguity Readiness Record", "Ambiguous Workflow Change Interpretation Brief", "Adaptive Prompt and Workflow Option Comparison Matrix", "Context Adaptation and Retrieval Risk Record", "Adaptive Workflow Test Coverage Plan", "Adaptive Test Evidence Evaluation Record", "Adaptive GenAI Workflow Design Recommendation Pack"]'::jsonb, '{"title": "Adapt GenAI Workflows for Complex and Ambiguous Conditions", "description": "Northstar Retail must adapt an existing GenAI workflow for a more complex customer-support environment involving incomplete requirements, competing business constraints, variable source quality, ambiguous user needs and higher operational risk. The learner must interpret ambiguity, compare design options, adapt prompt and context strategies, expand test coverage, evaluate evidence and recommend a defensible workflow design with clear trade-offs, assumptions, residual risks and escalation points. The learner may recommend adaptive changes but may not bypass governance, make unsupported policy decisions or independently authorise production release."}'::jsonb, 420, 'advanced'::public.difficulty_level, 'published'::public.status, 1, TRUE)
ON CONFLICT DO NOTHING;
INSERT INTO public."levels" ("id", "level_code", "capability_id", "level_id", "title", "description", "observable_behavior", "example_outputs", "problem_statement", "duration_minutes", "difficulty_level", "status", "version_no", "is_active")
VALUES ('3aa64007-0085-5217-9951-c1f64ff9ee7c'::uuid, 'CAP037_L5', (SELECT "id" FROM public."capabilities" WHERE "code" = 'ITS-CAP-037'), (SELECT "id" FROM public."level_scale" WHERE "level_no" = 5), 'Govern and Scale GenAI Workflow Design Practice', 'Northstar Retail is scaling GenAI workflow use across teams and needs consistent design standards, reusable patterns, evaluation controls, reviewer capability and governance evidence. Current workflows show inconsistent prompt structures, uneven context controls, fragmented evaluation practices, repeated defects and variable reviewer judgement. The learner must define standards, create reusable pattern guidance, design evaluation and governance controls, analyse systemic weaknesses, coach reviewers and produce a governance-and-scale pack that improves practice across multiple workflows. The learner must preserve accountable ownership, legal, privacy, security and production-approval boundaries.', '["Define workflow design standards", "create governed prompt and context patterns", "design evaluation and governance controls", "analyse systemic weaknesses", "coach reviewers", "govern and scale workflow practice"]'::jsonb, '["Leadership Authority and Governance Readiness Record", "GenAI Workflow Design Standard", "Prompt and Context Pattern Library Entry", "Evaluation and Governance Control Plan", "Systemic Workflow Weakness Analysis", "Reviewer Coaching and Practice Improvement Plan", "GenAI Workflow Governance and Scale Pack"]'::jsonb, '{"title": "Govern and Scale GenAI Workflow Design Practice", "description": "Northstar Retail is scaling GenAI workflow use across teams and needs consistent design standards, reusable patterns, evaluation controls, reviewer capability and governance evidence. Current workflows show inconsistent prompt structures, uneven context controls, fragmented evaluation practices, repeated defects and variable reviewer judgement. The learner must define standards, create reusable pattern guidance, design evaluation and governance controls, analyse systemic weaknesses, coach reviewers and produce a governance-and-scale pack that improves practice across multiple workflows. The learner must preserve accountable ownership, legal, privacy, security and production-approval boundaries."}'::jsonb, 420, 'expert'::public.difficulty_level, 'published'::public.status, 1, TRUE)
ON CONFLICT DO NOTHING;

